import { execFileSync } from "node:child_process";
import { mkdirSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import zlib from "node:zlib";
import { build } from "esbuild";

const root = "C:/dev/runs/rbab9148349";
const tmp = join(root, ".tmp-baseline");

const files = execFileSync("git", ["ls-tree", "-r", "--name-only", "HEAD", "src"], {
  cwd: root,
  encoding: "utf8",
})
  .trim()
  .split("\n");
for (const file of files) {
  const content = execFileSync("git", ["show", `HEAD:${file}`], { cwd: root, encoding: "utf8" });
  const dest = join(tmp, file);
  mkdirSync(dirname(dest), { recursive: true });
  writeFileSync(dest, content);
}

const entries = {
  H3Core: `import { H3Core } from "SRC/index.ts"; const app = new H3Core();`,
  defineHandler: `import { defineHandler } from "SRC/index.ts"; const handler = defineHandler({});`,
};

async function measure(srcRoot, code) {
  const res = await build({
    bundle: true,
    metafile: true,
    write: false,
    minify: true,
    format: "esm",
    platform: "node",
    outfile: "index.mjs",
    treeShaking: true,
    conditions: ["browser"],
    logOverride: { "ignored-bare-import": "silent" },
    stdin: {
      contents: code.replaceAll("SRC", srcRoot),
      resolveDir: join(root, "test/bench"),
      sourcefile: "index.mjs",
      loader: "js",
    },
  });
  const bytes = res.metafile.outputs["index.mjs"].bytes;
  const gzip = zlib.gzipSync(res.outputFiles[0].text).byteLength;
  return { bytes, gzip };
}

for (const [label, srcRoot] of [
  ["HEAD", join(tmp, "src").replaceAll("\\", "/")],
  ["working tree", join(root, "src").replaceAll("\\", "/")],
]) {
  for (const [name, code] of Object.entries(entries)) {
    console.log(label, name, JSON.stringify(await measure(srcRoot, code)));
  }
}

